  ensures len(strings) == 0 ==> r == []
  ensures len(strings) > 0 ==> (forall i in [0, n) . i < len(strings) ==> strings[i][0..len(r)] == r)
  ensures len(strings) > 0 ==> (forall i in [0, n) . i < len(strings) ==> len(r) <= len(strings[i]))
  ensures len(strings) > 0 ==> (forall k in [len(r) + 1, (forall i in [0, n) . i < len(strings) ==> len(strings[i])] + 1) . (exists i in [0, n) . i < len(strings) and k <= len(strings[i]) and strings[i][0..k] != r + [strings[i][len(r)]]) or (forall i in [0, n) . i < len(strings) ==> len(strings[i]) <= len(r)))
{
  if n == 0 or len(strings) == 0 {
    r := [];
  } else {
    var prefix: seq := strings[0][0..len(strings[0])];
    var i: int := 1;
    while i < n and i < len(strings) and len(prefix) > 0
      invariant i >= 1
      invariant i <= n
      invariant i <= len(strings)
      invariant len(prefix) >= 0
      invariant (forall j in [0, i) . j < len(strings) ==> strings[j][0..len(prefix)] == prefix)
      invariant (forall j in [0, i) . j < len(strings) ==> len(prefix) <= len(strings[j]))
